# Compiler

def escape_literal_content(content_list):
    # content_list is list of strings each is either single char or escape like \n etc.
    # Need to produce regex escaped version
    out = []
    specials = set(r".*+?|()[]{}^$\/")
    # Actually '-' not special outside class, but inside class? For literal we escape specials for regex
    # From earlier test: . * + ? | ( ) [ ] { } ^ $ \ / need escape? But we saw / -> / not escaped, but \/ -> \/ ?
    # Let's map: content_list may contain escapes like \" , \\ , \/ , \b etc.
    # For each element, if it's an escape like \n, keep as \n (two chars) but for regex output, \n should be \n (two chars) ? Earlier test showed `"a\n"` -> `a\n` (a, backslash, n) . So \n stays as \n.
    # Similarly \t -> \t, \r -> \r, \b -> \b, \f -> \f, \" -> ", \\ -> \, \/ -> \/ ?
    # For \/ -> in literal, we saw `"\/"` output `\/`? Let's check: earlier `"\/"` gave `\/`? Actually test with `"/"` gave `/`, and `"\/"` gave `\/`. So \/ is allowed and outputs \/.
    # For \\ -> \
    # For \" -> " (no escape needed in regex, just ")
    for item in content_list:
        if len(item)==2 and item[0]=='\\':
            esc = item[1]
            if esc == 'n':
                out.append('\\n')
            elif esc == 't':
                out.append('\\t')
            elif esc == 'r':
                out.append('\\r')
            elif esc == 'b':
                out.append('\\b')
            elif esc == 'f':
                out.append('\\f')
            elif esc == '\\':
                out.append('\\\\')
            elif esc == '"':
                out.append('"')
            elif esc == '/':
                out.append('\\/')
            else:
                out.append(item) # should not happen
        else:
            # single char
            ch = item
            if ch == '\\':
                out.append('\\\\')
            elif ch in specials:
                # need to escape with \
                # For specials, we saw `"a"` with a not special, but `"."` gives `\\.`
                # So for each char in content that is special, prefix \
                # But what about characters that are not special but need no escape: letters, digits, space etc.
                # For literal `"a b"` -> `a b` (space not escaped)
                # For literal `"-"` -> `-` (dash not escaped outside class)
                # So check set
                if ch == '/':
                    out.append('/')
                else:
                    out.append('\\' + ch)
            else:
                out.append(ch)
    return ''.join(out)

def compile_literal(node):
    return escape_literal_content(node["content"])

def compile_raw(node):
    return node["content"]

def compile_symbol(node):
    name = node["name"]
    return ALLOWED_SYMBOLS[name]

def compile_not_symbol(node):
    name = node["symbol"]["name"]
    if name in NEGATED_SYMBOLS:
        return NEGATED_SYMBOLS[name]
    else:
        # for <space>, <newline>, etc -> [^X]
        val = ALLOWED_SYMBOLS[name]
        # val may be " " or "\n" etc
        # For [^ , need to handle escape inside? e.g., not <newline> => [^\n]
        # For space => [^ ]
        if name == "space":
            return "[^ ]"
        elif name == "newline":
            return "[^\\n]"
        elif name == "tab":
            return "[^\\t]"
        elif name == "return":
            return "[^\\r]"
        elif name == "feed":
            return "[^\\f]"
        elif name == "null":
            return "[^\\0]"
        else:
            # fallback
            return f"[^{val}]"

def compile_range(node):
    start = node["start"]
    end = node["end"]
    # Need to escape for class? Original handles '-' as literal inside class: a to z => [a-z], - to z => [--z], etc.
    # For endpoints that are special inside class like ], [, \, ^, -, we saw outputs like []-z], [[-z], [\ -z], [^-z], [--z]
    # So they just put start and end directly without extra escaping except for \, ], etc? Let's see observed:
    # start ']' => '[]-z]' -> they escaped ']'? Input ']' to z; gave '[]-z]' which is `[` + `]` + `-` + `z` + `]`? Actually `[ ]-z]` has opening `[`, then `]`, then `-`, then `z`, then `]`. That's weird but they allow.
    # start '[' => '[[-z]'
    # start '^' => '[^-z]' -> ^ at start would need escape? But they output `[^-z]` where first after [ is ^? That's negated? Actually `[^-z]` with ^ at first position after [ means negated? But they treat `^ to z` as `[^-z]` which is ambiguous but they output.
    # start '\' => '[\-z]' -> they escape backslash as `\\` ?
    # We'll implement: for class, we need to escape `]`? But original allows `]` as first char after `[` without escape.
    # Let's mimic: just directly use start and end as chars, but if start == '\', produce '\\', if end == '\', etc. For ] we may need to handle.
    # For our observed cases:
